content:
:root {
  --bg-main: #0b0f19;
  --bg-panel: rgba(22, 30, 46, 0.85);
  --bg-panel-border: rgba(99, 102, 241, 0.2);
  --primary-color: #6366f1;
  --primary-hover: #4f46e5;
  --secondary-color: #3b82f6;
  --secondary-hover: #2563eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --slider-track: #1e293b;
  --slider-thumb: #818cf8;
  --badge-bg: rgba(99, 102, 241, 0.15);
  --badge-border: rgba(99, 102, 241, 0.4);
  --badge-text: #a5b4fc;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-glow: 0 4px 20px -2px rgba(99, 102, 241, 0.25);
  --shadow-canvas: 0 10px 30px -5px rgba(0, 0, 0, 0.5);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--bg-main);
  color: var(--text-main);
  font-family: var(--font-family);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

/* 全体ラッパー */
.app-wrapper {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px 20px 28px;
  gap: 16px;
}

/* ヘッダーエリア */
.app-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 8px;
  padding: 8px 0;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #a5b4fc 0%, #818cf8 50%, #c084fc 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  display: inline-block;
}

.app-description {
  font-size: 0.925rem;
  color: var(--text-muted);
  max-width: 600px;
  line-height: 1.5;
}

/* シミュレーション領域レイアウト */
.sim-container {
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex: 1;
  align-items: stretch;
}

@media (min-width: 900px) {
  .sim-container {
    flex-direction: row;
    align-items: flex-start;
  }
}

/* キャンバス描画エリア */
.canvas-area {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 30%, #171f33 0%, #0d121f 100%);
  border: 1px solid var(--bg-panel-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-canvas);
  overflow: hidden;
  min-height: 400px;
  max-height: 70vh;
  touch-action: none;
}

.canvas-area canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: crosshair;
}

/* キャンバス上のヒントテキスト */
.hint-text {
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.85rem;
  color: rgba(248, 250, 252, 0.7);
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(8px);
  padding: 6px 14px;
  border-radius: 9999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  pointer-events: none;
  white-space: nowrap;
  letter-spacing: 0.02em;
}

/* コントロールパネル */
.control-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  background: var(--bg-panel);
  backdrop-filter: blur(12px);
  border: 1px solid var(--bg-panel-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-glow);
  width: 100%;
}

@media (min-width: 900px) {
  .control-panel {
    width: 320px;
    flex-shrink: 0;
  }
}

/* 統計・バッジエリア */
.stats-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.stats-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.825rem;
  font-weight: 600;
  color: var(--badge-text);
  background: var(--badge-bg);
  border: 1px solid var(--badge-border);
  padding: 4px 10px;
  border-radius: 9999px;
}

/* 各スライダーコントロールのグループ */
.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.control-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-main);
}

.control-value {
  font-size: 0.825rem;
  font-weight: 600;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  color: var(--badge-text);
  background: rgba(15, 23, 42, 0.6);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

/* スライダーのスタイリング */
.control-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: var(--slider-track);
  border-radius: 9999px;
  outline: none;
  transition: opacity 0.2s;
  cursor: pointer;
}

.control-slider:hover {
  opacity: 0.9;
}

.control-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--slider-thumb);
  cursor: pointer;
  box-shadow: 0 0 10px rgba(129, 140, 248, 0.6);
  transition: transform 0.1s ease, box-shadow 0.1s ease;
  border: 2px solid #ffffff;
}

.control-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  box-shadow: 0 0 14px rgba(129, 140, 248, 0.8);
}

.control-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--slider-thumb);
  cursor: pointer;
  box-shadow: 0 0 10px rgba(129, 140, 248, 0.6);
  border: 2px solid #ffffff;
}

/* ボタン群 */
.button-group {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  margin-top: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 14px;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  color: #ffffff;
  outline: none;
  user-select: none;
}

.btn:active {
  transform: scale(0.97);
}

/* ボタンバリエーション */
.btn-primary {
  grid-column: span 2;
  background: linear-gradient(135deg, var(--primary-color) 0%, var(--primary-hover) 100%);
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.35);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #4f46e5 0%, #4338ca 100%);
  box-shadow: 0 6px 16px rgba(99, 102, 241, 0.45);
}

.btn-secondary {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: var(--text-main);
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.25);
}

.btn-danger {
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.35);
  color: #fca5a5;
}

.btn-danger:hover {
  background: var(--danger-color);
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.35);
}

/* スマホ等小型端末向け最適化 */
@media (max-width: 480px) {
  .app-wrapper {
    padding: 12px 12px 20px;
    gap: 12px;
  }

  .app-title {
    font-size: 1.4rem;
  }

  .app-description {
    font-size: 0.825rem;
  }

  .canvas-area {
    min-height: 320px;
  }

  .control-panel {
    padding: 16px;
    gap: 14px;
  }

  .btn {
    padding: 9px 10px;
    font-size: 0.825rem;
  }
}

export interface PhysicsBall {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  bounce: number;
}

export interface SimConfig {
  gravity: number;
  bounceRatio: number;
  friction: number;
}

export interface ControlsProps {
  config: SimConfig;
  onChangeConfig: (newConfig: SimConfig) => void;
  ballCount: number;
  onAddBall: () => void;
  onClearBalls: () => void;
  onResetBalls: () => void;
}

import { ChangeEvent } from 'react';
import { ControlsProps } from '../types';

const Controls = ({
  config,
  onChangeConfig,
  ballCount,
  onAddBall,
  onClearBalls,
  onResetBalls,
}: ControlsProps) => {
  const handleGravityChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig?.({
      ...config,
      gravity: parseFloat(e.target.value),
    });
  };

  const handleBounceChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig?.({
      ...config,
      bounceRatio: parseFloat(e.target.value),
    });
  };

  const handleFrictionChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig?.({
      ...config,
      friction: parseFloat(e.target.value),
    });
  };

  return (
    <div className="control-panel">
      <div className="stats-container">
        <span style={{ fontSize: '0.875rem', fontWeight: 600 }}>ボール情報</span>
        <div className="stats-badge">
          <span>●</span>
          <span>{ballCount} 個のボール</span>
        </div>
      </div>

      <div className="control-group">
        <label className="control-label" htmlFor="gravity-slider">
          <span>重力の強さ</span>
          <span className="control-value">{config.gravity.toFixed(2)} G</span>
        </label>
        <input
          id="gravity-slider"
          className="control-slider"
          type="range"
          min="0.0"
          max="1.5"
          step="0.02"
          value={config.gravity}
          onChange={handleGravityChange}
        />
      </div>

      <div className="control-group">
        <label className="control-label" htmlFor="bounce-slider">
          <span>反発係数 (弾性)</span>
          <span className="control-value">{(config.bounceRatio * 100).toFixed(0)}%</span>
        </label>
        <input
          id="bounce-slider"
          className="control-slider"
          type="range"
          min="0.1"
          max="0.98"
          step="0.02"
          value={config.bounceRatio}
          onChange={handleBounceChange}
        />
      </div>

      <div className="control-group">
        <label className="control-label" htmlFor="friction-slider">
          <span>空気抵抗 (保持率)</span>
          <span className="control-value">{(config.friction * 100).toFixed(1)}%</span>
        </label>
        <input
          id="friction-slider"
          className="control-slider"
          type="range"
          min="0.970"
          max="1.000"
          step="0.002"
          value={config.friction}
          onChange={handleFrictionChange}
        />
      </div>

      <div className="button-group">
        <button
          type="button"
          className="btn btn-primary"
          onClick={() => onAddBall?.()}
        >
          ＋ ランダムボール追加
        </button>
        <button
          type="button"
          className="btn btn-secondary"
          onClick={() => onResetBalls?.()}
        >
          リセット
        </button>
        <button
          type="button"
          className="btn btn-danger"
          onClick={() => onClearBalls?.()}
        >
          全消去
        </button>
      </div>
    </div>
  );
};

export default Controls;

import { useState, useRef, useEffect, useCallback } from 'react';
import { PhysicsBall, SimConfig } from './types';
import Controls from './components/Controls';
import './index.css';

const COLOR_PALETTE = [
  '#f43f5e',
  '#ec4899',
  '#d946ef',
  '#a855f7',
  '#8b5cf6',
  '#6366f1',
  '#3b82f6',
  '#0ea5e9',
  '#06b6d4',
  '#14b8a6',
  '#10b981',
  '#22c55e',
  '#eab308',
  '#f97316',
];

const DEFAULT_CONFIG: SimConfig = {
  gravity: 0.45,
  bounceRatio: 0.82,
  friction: 0.994,
};

const createInitialBalls = (width: number, height: number): PhysicsBall[] => {
  const safeW = Math.max(width, 300);
  const safeH = Math.max(height, 300);
  const balls: PhysicsBall[] = [];

  for (let i = 0; i < 5; i++) {
    const radius = 16 + (i % 3) * 6;
    balls.push({
      id: i + 1,
      x: (safeW / 6) * (i + 1),
      y: safeH * 0.2 + (i % 2) * 40,
      vx: (i % 2 === 0 ? 1 : -1) * (2 + i * 0.7),
      vy: -1.5 * i,
      radius,
      color: COLOR_PALETTE[i % COLOR_PALETTE.length],
      bounce: 0.8 + (i % 3) * 0.05,
    });
  }
  return balls;
};

const App = () => {
  const [config, setConfig] = useState<SimConfig>(DEFAULT_CONFIG);
  const [ballCount, setBallCount] = useState<number>(5);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const ballsRef = useRef<PhysicsBall[]>([]);
  const configRef = useRef<SimConfig>(DEFAULT_CONFIG);
  const animationFrameIdRef = useRef<number | null>(null);
  const nextBallIdRef = useRef<number>(6);

  useEffect(() => {
    configRef.current = config;
  }, [config]);

  const addBallAt = useCallback((x: number, y: number, customVx?: number, customVy?: number) => {
    const radius = Math.floor(Math.random() * 16) + 14;
    const randomColor = COLOR_PALETTE[Math.floor(Math.random() * COLOR_PALETTE.length)];
    const vx = customVx !== undefined ? customVx : (Math.random() - 0.5) * 8;
    const vy = customVy !== undefined ? customVy : (Math.random() - 0.7) * 7;
    const bounce = 0.75 + Math.random() * 0.2;

    const newBall: PhysicsBall = {
      id: nextBallIdRef.current++,
      x,
      y,
      vx,
      vy,
      radius,
      color: randomColor,
      bounce,
    };

    ballsRef.current.push(newBall);
    setBallCount(ballsRef.current.length);
  }, []);

  const handleAddRandomBall = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const x = canvas.width * (0.2 + Math.random() * 0.6);
    const y = canvas.height * 0.2;
    addBallAt(x, y);
  }, [addBallAt]);

  const handleClearBalls = useCallback(() => {
    ballsRef.current = [];
    setBallCount(0);
  }, []);

  const handleResetBalls = useCallback(() => {
    const canvas = canvasRef.current;
    const w = canvas ? canvas.width : 600;
    const h = canvas ? canvas.height : 450;
    ballsRef.current = createInitialBalls(w, h);
    nextBallIdRef.current = ballsRef.current.length + 1;
    setConfig(DEFAULT_CONFIG);
    setBallCount(ballsRef.current.length);
  }, []);

  const handleCanvasPointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const initialVx = (Math.random() - 0.5) * 10;
    const initialVy = -4 - Math.random() * 5;
    addBallAt(x, y, initialVx, initialVy);
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const handleResize = () => {
      const { width, height } = container.getBoundingClientRect();
      if (width > 0 && height > 0) {
        canvas.width = Math.floor(width);
        canvas.height = Math.floor(height);

        if (ballsRef.current.length === 0) {
          ballsRef.current = createInitialBalls(canvas.width, canvas.height);
          setBallCount(ballsRef.current.length);
        } else {
          ballsRef.current.forEach((b) => {
            b.x = Math.max(b.radius, Math.min(canvas.width - b.radius, b.x));
            b.y = Math.max(b.radius, Math.min(canvas.height - b.radius, b.y));
          });
        }
      }
    };

    handleResize();

    const resizeObserver = new ResizeObserver(() => {
      handleResize();
    });
    resizeObserver.observe(container);

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const render = () => {
      const curConfig = configRef.current;
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      ctx.save();
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
      ctx.lineWidth = 1;
      const gridSize = 40;
      for (let x = 0; x < w; x += gridSize) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
        ctx.stroke();
      }
      for (let y = 0; y < h; y += gridSize) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }
      ctx.restore();

      const balls = ballsRef.current;
      const len = balls.length;

      for (let i = 0; i < len; i++) {
        for (let j = i + 1; j < len; j++) {
          const b1 = balls[i];
          const b2 = balls[j];
          const dx = b2.x - b1.x;
          const dy = b2.y - b1.y;
          const dist = Math.hypot(dx, dy);
          const minDist = b1.radius + b2.radius;

          if (dist < minDist && dist > 0) {
            const overlap = 0.5 * (minDist - dist);
            const nx = dx / dist;
            const ny = dy / dist;

            b1.x -= nx * overlap;
            b1.y -= ny * overlap;
            b2.x += nx * overlap;
            b2.y += ny * overlap;

            const kx = b1.vx - b2.vx;
            const ky = b1.vy - b2.vy;
            const p = 2 * (nx * kx + ny * ky) / (b1.radius + b2.radius);

            const effectiveBounce = ((b1.bounce + b2.bounce) / 2) * curConfig.bounceRatio;

            b1.vx -= p * b2.radius * nx * effectiveBounce;
            b1.vy -= p * b2.radius * ny * effectiveBounce;
            b2.vx += p * b1.radius * nx * effectiveBounce;
            b2.vy += p * b1.radius * ny * effectiveBounce;
          }
        }
      }

      for (let i = 0; i < len; i++) {
        const ball = balls[i];

        ball.vy += curConfig.gravity;

        ball.vx *= curConfig.friction;
        ball.vy *= curConfig.friction;

        ball.x += ball.vx;
        ball.y += ball.vy;

        const combinedBounce = ball.bounce * curConfig.bounceRatio;

        if (ball.y + ball.radius > h) {
          ball.y = h - ball.radius;
          ball.vy = -ball.vy * combinedBounce;
          ball.vx *= 0.98;
          if (Math.abs(ball.vy) < 0.25) {
            ball.vy = 0;
          }
        }

        if (ball.y - ball.radius < 0) {
          ball.y = ball.radius;
          ball.vy = -ball.vy * combinedBounce;
        }

        if (ball.x + ball.radius > w) {
          ball.x = w - ball.radius;
          ball.vx = -ball.vx * combinedBounce;
        }

        if (ball.x - ball.radius < 0) {
          ball.x = ball.radius;
          ball.vx = -ball.vx * combinedBounce;
        }

        ctx.save();
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);

        const gradient = ctx.createRadialGradient(
          ball.x - ball.radius * 0.35,
          ball.y - ball.radius * 0.35,
          ball.radius * 0.1,
          ball.x,
          ball.y,
          ball.radius
        );
        gradient.addColorStop(0, '#ffffff');
        gradient.addColorStop(0.3, ball.color);
        gradient.addColorStop(1, '#090d16');

        ctx.fillStyle = gradient;
        ctx.shadowColor = ball.color;
        ctx.shadowBlur = 12;
        ctx.fill();

        ctx.lineWidth = 1.5;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.stroke();

        ctx.beginPath();
        ctx.ellipse(
          ball.x,
          h - 3,
          Math.max(2, ball.radius * (1 - Math.min(1, (h - ball.y) / (h * 0.7)))),
          3,
          0,
          0,
          Math.PI * 2
        );
        ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
        ctx.shadowBlur = 0;
        ctx.fill();

        ctx.restore();
      }

      animationFrameIdRef.current = requestAnimationFrame(render);
    };

    animationFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      if (animationFrameIdRef.current !== null) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
      resizeObserver.disconnect();
    };
  }, []);

  return (
    <div className="app-wrapper">
      <header className="app-header">
        <h1 className="app-title">物理演算バウンスシミュレーター</h1>
        <p className="app-description">
          重力・跳ね返り・摩擦をリアルタイムに計算する物理シミュレーションです。
          キャンバスをクリックやタップして自由な位置にボールを弾き出せます。
        </p>
      </header>

      <main className="sim-container">
        <div className="canvas-area" ref={containerRef}>
          <canvas
            ref={canvasRef}
            onPointerDown={handleCanvasPointerDown}
          />
          <div className="hint-text">
            💡 クリック・タップでボールを撃ち出す
          </div>
        </div>

        <Controls
          config={config}
          onChangeConfig={setConfig}
          ballCount={ballCount}
          onAddBall={handleAddRandomBall}
          onClearBalls={handleClearBalls}
          onResetBalls={handleResetBalls}
        />
      </main>
    </div>
  );
};

export default App;
